mapper.select:
SELECT d.device_id AS deviceId, d.community_id AS communityId, d.building_id AS buildingId, d.unit_id AS unitId, d.device_name AS deviceName, d.device_code AS deviceCode, d.device_type AS deviceType, d.device_location AS deviceLocation, d.device_status AS deviceStatus, d.online_status AS onlineStatus, d.manufacturer AS manufacturer, d.install_date AS installDate, d.last_maintain_time AS lastMaintainTime, d.next_maintain_time AS nextMaintainTime, d.alarm_status AS alarmStatus, d.alarm_content AS alarmContent, d.create_by AS createBy, d.create_time AS createTime, d.update_by AS updateBy, d.update_time AS updateTime, d.remark AS remark, c.community_name AS communityName, b.building_name AS buildingName, u.unit_name AS unitName FROM community_device d LEFT JOIN community c ON c.community_id = d.community_id LEFT JOIN building b ON b.building_id = d.building_id LEFT JOIN unit u ON u.unit_id = d.unit_id
AND d.community_id = #{q.communityId}
AND 1 = 0
AND d.community_id IN
#{cid}
AND d.building_id = #{q.buildingId}
AND d.unit_id = #{q.unitId}
AND d.device_name LIKE CONCAT('%', #{q.deviceName}, '%')
AND d.device_code LIKE CONCAT('%', #{q.deviceCode}, '%')
AND d.device_type = #{q.deviceType}
AND d.device_status = #{q.deviceStatus}
AND d.online_status = #{q.onlineStatus}
AND d.alarm_status = #{q.alarmStatus}
ORDER BY d.create_time DESC, d.device_id DESC
